import{z as o,x as n,o as E,c as m,q as B,j as l,D as e,d as t,s as A,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"波动率仓位的账本","description":"","frontmatter":{"title":"波动率仓位的账本","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/omm-vol-position-ledger.md","filePath":"quant/omm-vol-position-ledger.md","lastUpdated":1791063341000}'),p={name:"quant/omm-vol-position-ledger.md"};function d(g,a,h,u,D,V){const i=n("Mermaid");return E(),m("div",null,[a[2]||(a[2]=B('<h1 id="波动率仓位的账本" tabindex="-1">波动率仓位的账本 <a class="header-anchor" href="#波动率仓位的账本" aria-label="Permalink to &quot;波动率仓位的账本&quot;">​</a></h1><div class="epigraph"><p>期权的存货是未来的波动，而波动没有仓库：它的库存价格每天由曲面重写一次。</p><footer>—— 据 Gatheral, The Volatility Surface；分桶与标记口径据做市实务整理</footer></div><p><a href="/quant/omm-book-layering">上一课</a>把成交钉到手层：批次、开平指定与逐层对账立住了账本的骨架。骨架上的肉是价格，而期权存货的价格不是标的价，是隐含波动。本课写波动率仓位的账本：把每一手按到期与分位折成 Vega，明确标记口径，让「这台子在做多还是做空哪一段波动」成为账本上可直接读出的一栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Delta 中性的期权簿，现货怎么走都不亏不赚，却仍然持有方向明确的波动仓位：卖出跨式是做空隐含波动、做多 Gamma。若账本只汇总一个总 Vega 数字，两个完全不同的台可以显示出同样的风险：一个卖近买远、一个买近卖远，总 Vega 相同，隐含期限结构一动，盈亏相反。缺的不是 Vega，而是<strong>按到期与分位展开</strong>的仓位，以及每格的标记价格——没有标记，未实现盈亏无从谈起。</p><p><span class="marginnote">直觉类比：只看总 Vega 像体检只报「体重合计」——两个人体重相同，一个肌肉多一个脂肪多，健康风险完全不同。按到期与分位分桶，就是把波动仓位按「体脂率」拆开看，才知道风险长在哪一节。</span></p><p>更深一层：标的账本的存货按成本计，市价每天给一次；波动仓位的存货价格是曲面拟合的产物，<a href="/quant/svi-ssvi">SVI / SSVI</a> 的参数一变，整本未实现盈亏重排。账本若不把「哪一段波动、按哪个标记」写成字段，盯市就成了可以事后辩论的软数。</p><h3 id="分桶与字段" tabindex="-1">分桶与字段 <a class="header-anchor" href="#分桶与字段" aria-label="Permalink to &quot;分桶与字段&quot;">​</a></h3><p>Vega 按到期切成期限桶（例如当周、当月、次月、远月），桶内再按 Delta 带或执行价区（ATM、风险反转、蝶式）细分，对上经纪商报 <a href="/quant/risk-reversal-skew">偏度交易</a> 的坐标。每一手在 <a href="/quant/omm-book-layering">手层</a> 记两个波动率：成交时的隐波与当前标记隐波，两者的 Vega 加权差就是该手的未实现波动盈亏。桶内汇总用 Vega 加权，而不是简单求和：一张深度虚值的期权 Vega 小但对翼部弯曲敏感，混进总数会看不见。</p><p><span class="marginnote">量级要随身带着：一张 \\(S=5000\\)、一个月期平值期权的 Vega 约为 \\(S\\sqrt{\\tau}\\,\\varphi(d_1)\\approx 5000\\times 0.29\\times 0.40\\approx 580\\)，即隐波动 1 个点价值动约 5.8；同一合约缩到一周，Vega 减半不止。这就是按到期分桶、不做一张总表的算术理由。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>日终流程四步。其一，重拟合或外推当日曲面，给每个到期桶定标记隐波；sticky 规则要事先定死——<a href="/quant/sticky-delta-strike">sticky delta 与 sticky strike</a> 下同一批仓位的标记变动完全不同。其二，逐手重估：Vega、Gamma、Theta 连同桶归属一并刷新，未实现盈亏按桶落账。其三，把已实现端接进来：<a href="/quant/gamma-scalping-pnl">Gamma scalping 的 PnL 恒等式</a> 说明，做多 Gamma 的台每天刮到的已实现方差与付出的 Theta 是同一笔账的两面，波动账本要给这两栏各留一列，别让它们混进「方向盈亏」。其四，出桶间报告：近月做空多少、远月做多多少、翼部净空多少，这是次日曲线维护的输入。</p><p><span class="marginnote">术语翻译：sticky strike 与 sticky delta 是曲面「固定方式」的两派约定：前者假设每个执行价的隐波不动（标的一动，平值隐波跟着换位置），后者假设隐波跟着 Delta 走。约定不同，同一批仓位当天的标记盈亏可以完全不同——所以必须在账本里事先定死用哪一派。</span></p>',13)),(E(),l(s,null,{default:e(()=>[A(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%89%8B%E5%B1%82%E6%89%B9%E6%AC%A1%22%5D%20--%3E%20B%5B%22%E6%88%90%E4%BA%A4%E9%9A%90%E6%B3%A2%20%E5%AF%B9%20%E6%A0%87%E8%AE%B0%E9%9A%90%E6%B3%A2%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%80%90%E6%89%8B%20Vega%20%E4%B8%8E%E6%9C%AA%E5%AE%9E%E7%8E%B0%E7%9B%88%E4%BA%8F%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%9C%9F%E9%99%90%E6%A1%B6%20%E6%B1%87%E6%80%BB%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%A1%B6%E5%86%85%20ATM%20RR%20BF%20%E5%88%86%E5%88%97%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%A1%B6%E9%97%B4%E6%8A%A5%E5%91%8A%20%E4%BE%9B%E6%AC%A1%E6%97%A5%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20F%20--%3E%20B%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"分桶账本为什么是必须而非奢侈：因为波动率曲面几乎从不平行移动。事件周近月隐波抬升而远月几乎不动，期限桶的盈亏拆分直接告诉你这台子赚的是事件溢价还是赔在了桶间错配；崩溃日偏斜变陡，ATM 桶与翼部桶符号相反。总 Vega 把这些全部加零。机制上，桶是曲面导数在仓位上的投影：曲面在第 \\(i\\) 桶动 \\(\\Delta\\sigma_i\\)，盈亏是 \\(\\sum_i \\nu_i\\,\\Delta\\sigma_i\\)，桶账本就是让这个和式的每一项都可问责。",-1)),(E(),l(s,null,{default:e(()=>[A(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%80%BB%20Vega%20%E4%B8%BA%E9%9B%B6%E7%9A%84%E8%B4%A6%E6%9C%AC%22%5D%20--%3E%20A%5B%22%E6%83%85%E6%99%AF%E4%B8%80%20%E4%BA%8B%E4%BB%B6%E5%91%A8%22%5D%0A%20%20P%20--%3E%20B%5B%22%E6%83%85%E6%99%AF%E4%BA%8C%20%E5%B4%A9%E6%BA%83%E6%97%A5%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E8%BF%91%E6%9C%88%E6%A1%B6%E9%9A%90%E6%B3%A2%E6%8A%AC%E5%8D%87%20%E8%BF%9C%E6%9C%88%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E8%BF%91%E6%9C%88%E7%A9%BA%E5%A4%B4%E4%BA%8F%20%E8%BF%9C%E6%9C%88%E7%99%BD%E6%8B%BF%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%81%8F%E6%96%9C%E5%8F%98%E9%99%A1%20ATM%20%E9%99%8D%20%E7%BF%BC%E9%83%A8%E5%8D%87%22%5D%0A%20%20B1%20--%3E%20B2%5B%22ATM%20%E6%A1%B6%E4%B8%8E%E7%BF%BC%E9%83%A8%E6%A1%B6%E7%9B%88%E4%BA%8F%E5%8F%8D%E5%8F%B7%22%5D%0A%20%20A2%20--%3E%20C%5B%22%E6%80%BB%20Vega%20%E4%BB%8D%E6%98%BE%E7%A4%BA%E4%B8%AD%E6%80%A7%20%E5%AE%9E%E9%99%85%E5%9C%A8%E4%BA%8F%22%5D%0A%20%20B2%20--%3E%20C%0A%20%20C%20--%3E%20D%5B%22%E6%A1%B6%E8%B4%A6%E6%9C%AC%E6%89%8D%E8%83%BD%E7%AD%94%20%E4%BA%8F%E5%9C%A8%E5%93%AA%E4%B8%80%E6%AE%B5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p>不这么做会错在哪：只用总 Vega 的台，在曲面扭转日看着「Vega 中性」的账本亏钱，却无法回答亏在哪一段；事后把桶补出来，桶归属又已随成交混在一起，无法复原。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>流动性差的翼部没有可靠报价，标记是模型观点，桶盈亏要带 haircut 看；Vega 是局部导数，隐波大动时 Volga 项主导，桶数字只给一阶印象。跨标的的波动仓位不可直接合并——指数波动与单票波动的相关结构是另一个账本。<a href="/quant/zero-dte-microstructure">0DTE</a> 桶的 Vega 在午后塌缩成近二元的形态，按普通桶管理会漏掉 <a href="/quant/pin-risk">Pin risk</a> 的形态。最后，桶划分本身是约定：换坐标（从到期到方差条带，如 <a href="/quant/vix-term-structure-trade">VIX 期限结构</a> 的三十天条带）会重排队列，报告口径变更必须留痕。</p><p><span class="marginnote">常见误区：初学者容易以为「Vega 中性 = 波动风险归零」。实际上 Vega 只是局部导数，隐波大幅跳动时 Volga（Vega 对波动的导数）接管盈亏；桶数字给的是一阶印象，大波动日要叠情景重估，不能拿中性两个字当护身符。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>期权存货的价格是隐含波动；波动账本的核心字段是每手的成交隐波与标记隐波。</li><li>Vega 按到期与分位分桶，桶内 Vega 加权；总 Vega 数会掩盖期限与偏斜的错配。</li><li>曲面移动几乎不平行，桶间拆分让扭转日的盈亏可问责。</li><li>已实现端（Gamma 刮取）与隐含端（Theta 支付）分列，混同即失去波动盈亏的解释力。</li><li>翼部标记是模型观点，0DTE 桶近二元，跨标的波动不可直加。</li><li>出处：据 Gatheral, <em>The Volatility Surface</em>；分桶、标记与对账口径据期权做市实务整理。</li></ul>',6))])}const C=o(p,[["render",d]]);export{f as __pageData,C as default};
